import type { PageConfig } from "../types";

/**
 * The media a greeting carries, normalised for rendering.
 *
 * `photos` is the deduplicated display list: the legacy primary photo first,
 * then the collage extras that are neither blank nor already shown. A video,
 * when present, supersedes the photos entirely — a player and a picture wall
 * competing for one page reads as an accident, and a video greeting usually
 * needs its caption page anyway.
 */
export interface PageMedia {
  photos: string[];
  videoUrl: string | null;
}

export function readPageMedia(page: PageConfig): PageMedia {
  const seen = new Set<string>();
  const push = (value: string | null | undefined) => {
    const url = value?.trim();
    if (url && !seen.has(url)) seen.add(url);
  };

  push(page.imageUrl);
  for (const url of page.photoUrls ?? []) push(url);

  const videoUrl = page.videoUrl?.trim() || null;

  return { photos: videoUrl ? [] : [...seen], videoUrl };
}

/** Whether the greeting has anything visual to split onto its own page. */
export function hasMedia(page: PageMedia): boolean {
  return page.photos.length > 0 || page.videoUrl !== null;
}

/**
 * How many columns the photo collage should use. One or two photos stay
 * full-width; beyond that they break into a balanced grid, with column counts
 * chosen so no count from one to six produces an awkward lone sliver.
 */
export function collageColumns(count: number): number {
  if (count <= 2) return Math.max(1, count);
  if (count === 4) return 2;
  return Math.min(3, count);
}
